questionvariables.text:
/* Pool rows: [id, line, self-explanation, paraphrase, monitoring]. */
pool: [
 ["L1", "\\((x - 1)(x + 1) = x \\times x + x \\times 1 + (-1) \\times x + (-1) \\times 1\\)",
  "Each term of the first bracket multiplies each term of the second, which is why there are four products.",
  "The right-hand side has been written out as four products added together.",
  "I am happy with this line and can follow it without any trouble."],
 ["L2", "\\(x^2 + x - x - 1 = x^2 - 1\\)",
  "The terms \\(+x\\) and \\(-x\\) add up to zero, which is why only \\(x^2\\) and \\(-1\\) are left.",
  "The four terms on the left simplify to \\(x^2 - 1\\) on the right.",
  "This step looks right to me, and I think I could do it myself."],
 ["L3", "Cut off the strip along the dashed line and move it to the side.",
  "Moving a piece does not change its area, so the new shape still has area \\(x^2 - 1\\).",
  "The strip along the top is cut off and placed against the side of the other piece.",
  "I would not have thought of cutting the shape like this, but I can see what happens."],
 ["L4", "The pieces now form a rectangle measuring \\(x + 1\\) by \\(x - 1\\).",
  "The strip is 1 high, so it adds 1 to the length \\(x\\); the height is \\(x - 1\\) because the strip came off the top.",
  "The two pieces fit together into a rectangle whose sides are \\(x + 1\\) and \\(x - 1\\).",
  "I had to look at the picture twice, but now I am fairly sure I follow it."],
 ["L5", "\\(-7 = 2 \\times (-4) + 1\\), so \\(-7\\) is odd.",
  "An odd number is \\(2k + 1\\) for some integer \\(k\\), and here \\(k = -4\\), which is an integer.",
  "Minus seven is two times minus four, plus one, and so minus seven is odd.",
  "This surprised me at first, because I am not used to negative odd numbers."]
];
vline: rand(pool);
perm: random_permutation([sexp, para, moni]);
commentof(c) := if c = sexp then vline[3] else if c = para then vline[4] else vline[5];
dd(c) := [[sexp, is(c = sexp), "self-explanation"], [para, is(c = para), "paraphrase"], [moni, is(c = moni), "monitoring"]];
diagof(c) := if c = sexp then para else sexp;
othrof(c) := if c = moni then para else moni;
leaddiag(c) := if c = sexp then "This comment adds something that is not in the line: a reason why the line is true. A paraphrase only restates the line."
  else if c = para then "This comment says the same as the line in other words, but gives no reason why it is true. A self-explanation gives a reason."
  else "This comment says how well the reader is following, not why the line is true. A self-explanation gives a reason.";
leadothr(c) := if c = sexp then "This comment does more than say how well the reader is following: it gives a reason for the line."
  else if c = para then "This comment is about the mathematics, not about how well the reader is following, but it only restates the line."
  else "This comment does not restate the line; it reports how the reader feels about it.";
kindsent(c) := if c = sexp then "This is a self-explanation: it gives a reason why the line is true."
  else if c = para then "This is a paraphrase: it restates the line without saying why it is true."
  else "This is monitoring: it reports how well the reader is following, not why the line is true.";
vtext: vline[2];
cat1: perm[1]; cat2: perm[2]; cat3: perm[3];
com1: commentof(cat1); com2: commentof(cat2); com3: commentof(cat3);
ta1: dd(cat1); ta2: dd(cat2); ta3: dd(cat3);
diag1: diagof(cat1); diag2: diagof(cat2); diag3: diagof(cat3);
othr1: othrof(cat1); othr2: othrof(cat2); othr3: othrof(cat3);
fbd1: leaddiag(cat1); fbd2: leaddiag(cat2); fbd3: leaddiag(cat3);
fbo1: leadothr(cat1); fbo2: leadothr(cat2); fbo3: leadothr(cat3);
/* Shown with a correct answer, so that the reason is stated once the kind has been found. */
fbt1: kindsent(cat1); fbt2: kindsent(cat2); fbt3: kindsent(cat3);
s_assert(is(length(unique([cat1, diag1, othr1])) = 3 and length(unique([cat2, diag2, othr2])) = 3 and length(unique([cat3, diag3, othr3])) = 3), true);
